using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 [InitializeOnLoad]public static class TabletopRevision {
  const string Key="TabletopRevisionCheck";static double started;static int frame;
  static string Root=>Path.GetFullPath("VerificationOutputs");
  static TabletopRevision(){if(SessionState.GetBool(Key,false)){started=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;}}
  public static void Install(){try{EditorSceneManager.OpenScene("Assets/Scenes/DoubleValley9x.unity");var world=UnityEngine.Object.FindObjectOfType<BattleWorld>();string[] troops=world.units.Select(u=>EditorJsonUtility.ToJson(u)).ToArray();foreach(var point in UnityEngine.Object.FindObjectsOfType<RecoveryPoint>())if(point.ownerId=="A"||point.ownerId=="B"){point.resourceStock=100000;PrefabUtility.RecordPrefabInstancePropertyModifications(point);}var importer=(TextureImporter)AssetImporter.GetAtPath("Assets/Game/Tabletop/ReferenceAtlas.png");importer.maxTextureSize=4096;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.npotScale=TextureImporterNPOTScale.None;importer.anisoLevel=8;importer.filterMode=FilterMode.Trilinear;importer.mipMapBias=-.35f;importer.SaveAndReimport();TabletopPresentation.NamePlaces();var camera=world.GetComponent<TabletopCamera>();if(camera==null)camera=world.gameObject.AddComponent<TabletopCamera>();camera.view=world.setup.mapCamera;camera.focus=Vector2.zero;camera.tilt=32;world.setup.mapCamera.orthographicSize=25;world.setup.zoomController.maximumSize=65;world.setup.zoomController.startAtMiddle=false;var opening=world.GetComponent<OpeningCameraFocus>();if(opening!=null)opening.enabled=false;var pan=world.GetComponent<MapPanController>();pan.keepViewportInsideMap=false;
   var presentation=world.GetComponent<TabletopPresentation>();if(presentation==null)presentation=world.gameObject.AddComponent<TabletopPresentation>();presentation.referenceAtlas=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Game/Tabletop/ReferenceAtlas.png");string materialPath="Assets/Game/Tabletop/WhiteAtlas.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(materialPath);if(material==null){material=new Material(Shader.Find("Campaign/WhiteAtlas"));AssetDatabase.CreateAsset(material,materialPath);}material.mainTexture=presentation.referenceAtlas;presentation.whiteAtlasMaterial=material;
   foreach(var p in UnityEngine.Object.FindObjectsOfType<RecoveryPoint>()){var marker=p.GetComponent<StaffObjectiveMarker>();if(marker!=null){marker.captionOverride="";EditorUtility.SetDirty(marker);}EditorUtility.SetDirty(p);}
   foreach(var s in UnityEngine.Object.FindObjectsOfType<ResourceSite>())EditorUtility.SetDirty(s);
   Check(world.units.Select((u,i)=>EditorJsonUtility.ToJson(u)==troops[i]).All(v=>v),"Initial army components unchanged by installation");EditorSceneManager.MarkSceneDirty(world.gameObject.scene);EditorSceneManager.SaveOpenScenes();AssetDatabase.SaveAssets();SessionState.SetString("TabletopInitialArmy",string.Join("|",world.units.Select(u=>u.gameObject.name).OrderBy(n=>n)));SessionState.SetBool(Key,true);started=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;
  }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
  static void Check(bool ok,string message){if(!ok)throw new Exception(message);Debug.Log("TABLETOP_PASS "+message);}
  static void Poll(){try{if(EditorApplication.timeSinceStartup-started>150)throw new Exception("Tabletop runtime timeout");if(!EditorApplication.isPlaying||Time.time<.7f)return;var world=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(world==null||!world.Initialized)return;if(frame++<3)return;world.enabled=false;foreach(var b in world.GetComponents<MonoBehaviour>())if(b is BattleAIController||b is AIBasicCommander)b.enabled=false;var orbit=world.GetComponent<TabletopCamera>();var view=orbit.view;Check(!view.orthographic,"Perspective table camera active");var points=new[]{new Vector3(-8,-3),new Vector3(3,4),new Vector3(12,-2)};foreach(var p in points){var s=view.WorldToScreenPoint(p);Check(Vector3.Distance(p,MapProjection.Ground(view,s))<.002f,"Perspective click projects onto map plane");}var focus=orbit.focus;orbit.Pan(Vector2.right,.25f);Check(orbit.focus.x>focus.x,"Horizontal camera panning moves focus");orbit.Orbit(new Vector2(30,15));Check(orbit.yaw!=0&&orbit.tilt>32,"Middle-button orbit changes yaw and tilt");foreach(var p in points)Check(Vector3.Distance(p,MapProjection.Ground(view,view.WorldToScreenPoint(p)))<.002f,"Rotated view retains accurate map targeting");var zoom=world.GetComponent<MapZoomController>();float old=view.orthographicSize;zoom.ScrollWheel(1);Check(view.orthographicSize<old&&!view.orthographic,"Wheel moves perspective camera closer");Debug.Log("TABLETOP_STOCK "+string.Join(",",world.points.Select(p=>p.ownerId+":"+p.resourceStock)));Check(world.points.Where(p=>p.ownerId=="A"||p.ownerId=="B").All(p=>p.resourceStock==100000),"Both starting factions retain 100000 resources");Debug.Log("ARMY_EXPECTED "+SessionState.GetString("TabletopInitialArmy",""));Debug.Log("ARMY_ACTUAL "+string.Join("|",world.units.Select(u=>u.gameObject.name).OrderBy(n=>n)));Check(SessionState.GetString("TabletopInitialArmy","").Split('|').All(n=>world.units.Any(u=>u.gameObject.name==n)),"Initial army roster preserved");Check(UnityEngine.Object.FindObjectsOfType<ResourceSite>().All(s=>s.displayName.All(c=>c<128)),"Resource names are English");Check(world.points.Where(p=>!p.isRepairSite).All(p=>p.displayName.All(c=>c<128)),"Village names are English");var minimap=TacticalMinimap.CameraView(view);Check(minimap.Contains(orbit.focus),"Minimap uses projected perspective footprint");Check(GameObject.Find("White atlas · lower sheet")!=null&&GameObject.Find("Raised paper edge")!=null,"White atlas and raised paper layers present");var border=world.GetComponent<PaperMapBorder>();Check(border!=null&&border.CoordinateLabels>30,"Map coordinates fixed to paper perimeter");Check(UnityEngine.Object.FindObjectsOfType<StaffViewportGrid>().Length==0,"Viewport-attached coordinate overlay removed");Check(Mathf.Abs(PaperMapBorder.Bite(1,0)-PaperMapBorder.Bite(2,0))>.001f,"Paper edge has deterministic irregular erosion");orbit.yaw=-8;orbit.tilt=32;orbit.Focus(Vector2.zero);zoom.SetSize(34);Directory.CreateDirectory(Root);Capture(view,"paper-edge-overview.png");orbit.Focus(new Vector2(-20,0));zoom.SetSize(13);Capture(view,"paper-edge-detail.png");orbit.Focus(new Vector2(border.Bounds.xMin+8,border.Bounds.yMin+2));zoom.SetSize(5);Capture(view,"paper-edge-closeup.png");File.WriteAllText(Path.Combine(Root,"tabletop-verification.txt"),"PASS perspective projection before/after orbit, horizontal movement, wheel dolly, English labels, layered backdrop, initial resources and army roster.\n");SessionState.SetBool(Key,false);EditorApplication.update-=Poll;EditorApplication.Exit(0);}catch(Exception e){SessionState.SetBool(Key,false);Debug.LogException(e);EditorApplication.Exit(1);}}
  static void Capture(Camera camera,string name){var rt=new RenderTexture(1600,1000,24);camera.targetTexture=rt;camera.Render();var active=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1600,1000,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,1000),0,0);image.Apply();File.WriteAllBytes(Path.Combine(Root,name),image.EncodeToPNG());RenderTexture.active=active;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(image);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
 }
}
